def has_zero(row):
    return 0 in row

def has_one(row):
    return 1 in row

def alternating_segment(segment, is_last=False):
    """Apply alternating 0/3 pattern to segment, starting from the end."""
    result = []
    if len(segment) % 2 == 1:
        # Odd length: starts with 3 from the end
        for i in range(len(segment)):
            if i % 2 == 0:
                result.append(3)
            else:
                result.append(0)
        return reversed(result), False
    else:
        # Even length: ends with 0 (middle boundary), starts with 3 if next is special
        # Actually let me use: alternate starting with 3 from the end
        for i in range(len(segment)-1, -1, -1):
            if (len(segment) - 1 - i) % 2 == 0:
                result.append(3)
            else:
                result.append(0)
        return result, True

def transform_row(row):
    """Transform a single row based on the pattern."""
    # Check if row has both 0 and 1 - that triggers transformation
    if not (has_zero(row) and has_one(row)):
        return row

    # Split into segments based on non-9 values (treating 9 as separator)
    segments = []
    current = []
    for val in row:
        if val != 9:
            current.append(val)
        else:
            if current:
                segments.append(current)
                current = []
    if current:
        segments.append(current)

    new_segments = []
    for seg_idx, seg in enumerate(segments):
        # Only transform segments that are all 0s
        if all(v == 0 for v in seg):
            transformed, _ = alternating_segment(seg)
            new_segments.append(transformed)
        else:
            new_segments.append(seg)

    # Reconstruct the row
    result = []
    seg_idx = 0
    for val in row:
        if val != 9:
            if seg_idx < len(new_segments):
                result.append(new_segments[seg_idx].pop(0))
            seg_idx += 1
        else:
            result.append(val)

    return result

